// The Teams page host (epic #3604) — renders the Teams workspace FROM THE GRAPH.
//
// Teams was the last of the five graph workspaces still resolved by the BUNDLER: `lazyWorkspaces`
// imported `TeamsPanel` through the feature barrel, so the 26 KB `teamspage` record was compiled into
// the bundle like any file. Every other rail destination with a page in the graph — glance, console,
// algorithms, data, sounds, logs, mcp, skills, automations, fleet — already mounts through a host.
// This closes that gap; it invents nothing.
//
// WHAT CHANGES, AND WHAT DOES NOT. The record is the same record either way. What moves is WHEN it is
// resolved: the loader esbuild-transforms `teamspage`'s source in the browser, keeps its platform
// imports external and answers them from the live `moduleRegistry`, and evaluates the result — so an
// edit to the record recompiles that node in the running app with no rebuild. The trade is that a
// mistake in the record now surfaces at RUNTIME rather than in `tsc`, which is exactly what the error
// boundary and the fallback below are for.
//
// The platform registrar runs at MODULE LOAD, before the workspace ever renders, so the injected
// modules are already in the registry when the compiled page's `require()` runs. It is idempotent.
//
// The stylesheet is loaded by the ENTRY's `@/**/*.css` glob (the-entry-owns-stylesheet-loading), not
// by a module import here: the runtime loader cannot resolve a CSS side-effect import, so a
// graph-hosted page must never depend on one.
import { GraphComponent } from "@/shared/lib/runtime/GraphComponent";
import { GraphPageFallback } from "@/shared/lib/runtime/GraphPageFallback";
import { registerTeamsPlatform } from "@/features/teams/graphPlatform";

// Register at module load — before the workspace ever renders — so the injected modules are in the
// registry when the graph page's compiled `require()` runs. Idempotent.
registerTeamsPlatform();

export function TeamsGraphHost({ pageOverride }: { pageOverride?: string } = {}) {
  // Fallback offers a one-click re-seed (#3648) when the source isn't in the library yet.
  return (
    <GraphComponent
      id="teamspage"
      exportName="TeamsPanel"
      props={pageOverride ? { pageOverride } : undefined}
      fallback={<GraphPageFallback page="Teams" icon="◎" />}
    />
  );
}
